SET NOCOUNT ON;
SELECT 'kucun' AS tbl, CASE WHEN lot_no IS NULL THEN 'NULL' WHEN RTRIM(lot_no)='' THEN 'EMPTY' WHEN RTRIM(lot_no)='PC0000' THEN 'PC0000' ELSE 'REAL' END AS cat, COUNT(*) n FROM kucun GROUP BY CASE WHEN lot_no IS NULL THEN 'NULL' WHEN RTRIM(lot_no)='' THEN 'EMPTY' WHEN RTRIM(lot_no)='PC0000' THEN 'PC0000' ELSE 'REAL' END
UNION ALL
SELECT 'inh', CASE WHEN 批号 IS NULL THEN 'NULL' WHEN RTRIM(批号)='' THEN 'EMPTY' WHEN RTRIM(批号)='PC0000' THEN 'PC0000' ELSE 'REAL' END, COUNT(*) FROM inh GROUP BY CASE WHEN 批号 IS NULL THEN 'NULL' WHEN RTRIM(批号)='' THEN 'EMPTY' WHEN RTRIM(批号)='PC0000' THEN 'PC0000' ELSE 'REAL' END
ORDER BY tbl, cat;
